<?php
namespace App\Console\Commands; use App\Services\Dapcode\AegisguardLoader; use App\Services\Dapcode\IntegrityService; use App\Services\Dapcode\LicenseGuard; use Illuminate\Console\Command; use Illuminate\Support\Str; class DapcodeAegisguardEncryptCommand extends Command { protected $signature = 'dapcode:aegisguard-encrypt {--force : Force encryption without interactive confirmation}'; protected $aliases = ['aegisguard:encrypt', 'dapcode:enc-aegisguard']; protected $description = 'Encrypt and minify AegisGuard core code files into AES-256-GCM (.enc) envelopes while keeping normal runtime execution'; public function __construct() { parent::__construct(); $this->setAliases(['aegisguard:encrypt', 'dapcode:enc-aegisguard']); } public function handle() { $this->info("======================================================="); $this->info("   DAPCODE AEGISGUARD — CORE CODE ENCRYPTION ENGINE     "); $this->info("======================================================="); $this->line("Mengenkripsi & me-minify seluruh file kode proteksi AegisGuard ke format .enc..."); $this->newLine(); $files = AegisguardLoader::getTargetAegisguardFiles(); if (empty($files)) { $this->error("Tidak ada file kode AegisGuard yang ditemukan."); return 1; } $this->line("Ditemukan <info>" . count($files) . "</info> file kode inti AegisGuard."); $force = (bool) $this->option('force'); if ( ! $force && $this->input->isInteractive()) { if ( ! $this->confirm("Apakah Anda yakin ingin mengenkripsi seluruh file kode AegisGuard ke dalam .enc?", true)) { $this->warn("Operasi dibatalkan oleh pengguna."); return 0; } } $bar = $this->output->createProgressBar(count($files)); $bar->start(); $results = []; $totalOriginal = 0; $totalMinified = 0; $totalSaved = 0; foreach ($files as $file) { $res = AegisguardLoader::encryptFile($file); if ($res['success']) { $relPath = Str::after($file, base_path() . DIRECTORY_SEPARATOR); $origSize = $res['original_size'] ?? 0; $miniSize = $res['minified_size'] ?? 0; $saved = $res['saved_bytes'] ?? 0; $totalOriginal += $origSize; $totalMinified += $miniSize; $totalSaved += $saved; $savedPercent = $origSize > 0 ? round(($saved / $origSize) * 100, 1) : 0; $results[] = [ 'file' => str_replace('\\', '/', $relPath), 'envelope' => str_replace('\\', '/', $relPath) . '.enc', 'status' => '<info>🔒 ENCRYPTED (.enc)</info>', 'orig' => $this->formatBytes($origSize), 'minified' => $this->formatBytes($miniSize), 'saved' => $this->formatBytes($saved) . " ({$savedPercent}%)", ]; } else { $relPath = Str::after($file, base_path() . DIRECTORY_SEPARATOR); $results[] = [ 'file' => str_replace('\\', '/', $relPath), 'envelope' => '-', 'status' => '<error>FAILED: ' . ($res['message'] ?? 'Error') . '</error>', 'orig' => '-', 'minified' => '-', 'saved' => '-', ]; } $bar->advance(); } $bar->finish(); $this->newLine(2); $this->table( ['File Target', 'Encrypted Envelope', 'Status', 'Original', 'Minified', 'Saved'], $results ); IntegrityService::recordCoreFilesManifest(); LicenseGuard::clearCache(); $this->callSilently('config:clear'); $totalPercent = $totalOriginal > 0 ? round(($totalSaved / $totalOriginal) * 100, 2) : 0; $this->info("======================================================="); $this->info(" [SELESAI] " . count($results) . " file kode AegisGuard berhasil dienkripsi ke .enc!"); $this->line(" Ukuran Total Awal     : <comment>" . $this->formatBytes($totalOriginal) . "</comment>"); $this->line(" Ukuran Total Minified : <info>" . $this->formatBytes($totalMinified) . "</info>"); $this->line(" Penghematan Ukuran    : <info>" . $this->formatBytes($totalSaved) . " ({$totalPercent}%)</info>"); $this->line(" Runtime Engine        : <info>AegisguardLoader JIT In-Memory AES-256-GCM</info>"); $this->info(" Status                : Sistem berjalan NORMAL secara penuh dengan file .enc!"); $this->line(" Perintah Dekripsi     : <comment>php artisan dapcode:aegisguard-decrypt</comment>"); $this->info("======================================================="); return 0; } protected function formatBytes($bytes, $precision = 2) { if ($bytes <= 0) { return '0 B'; } $units = ['B', 'KB', 'MB', 'GB']; $base = log($bytes, 1024); $pow = floor($base); return round(pow(1024, $base - $pow), $precision) . ' ' . ($units[$pow] ?? 'B'); } }